questionvariables.text:
/* Typical trip with no information */
typical: 60;

/* Day x time adjustments (rows = days Mon..Sun, columns = times) and their rounded averages */
dayL: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
timeL: ["05:30", "08:00", "13:00", "17:30", "19:30", "23:00"];
H: [[-15, 15, -5, 20, 10, -20], [-15, 10, -5, 20, 10, -20], [-15, 10, -5, 20, 10, -20], [-15, 10, -5, 25, 15, -20], [-15, 10, 0, 35, 30, -10], [-20, -10, 0, 5, 5, -15], [-20, -15, -10, -5, 0, -20]];
dayM: [1, 0, 0, 2, 8, -6, -12];
timeM: [-16, 4, -4, 17, 11, -18];

/* Other clues and the minutes each adds to the typical trip */
areaL: ["Westlands", "Kilimani", "Embakasi", "Kasarani", "Karen", "Ruaka", "Rongai"];
areaE: [-10, -10, 0, 0, 5, 5, 15];
wxL: ["Dry", "Light rain", "Heavy rain"];
wxE: [-5, 5, 15];
newsL: ["No incidents", "Crash on Thika Road", "Roadworks on Ngong Road", "Burst water main, Haile Selassie Ave"];
newsE: [-5, 15, 15, 15];
rateL: ["4.6 stars", "4.7 stars", "4.8 stars", "4.9 stars"];

/* Random trip: incidents and heavy rain are less common */
di: rand(7) + 1;
ti: rand(6) + 1;
ai: rand(7) + 1;
wi: rand([1, 1, 1, 2, 3]);
ni: rand([1, 1, 1, 1, 1, 1, 2, 3, 4]);
ri: rand(4) + 1;
noise: rand_with_step(-5, 5, 1);

/* Card order: 1 Day, 2 Time of day, 3 Pickup point, 4 Weather, 5 Traffic news, 6 Driver rating */
cardn: ["Day", "Time of day", "Pickup point", "Weather", "Traffic news", "Driver rating"];
cardv: [dayL[di], timeL[ti], areaL[ai], wxL[wi], newsL[ni], rateL[ri]];
dt: H[di][ti];
eff: [0, 0, areaE[ai], wxE[wi], newsE[ni], 0];
actual: typical + dt + eff[3] + eff[4] + eff[5] + noise;

/* Signed strings for display, e.g. "+10", "-5", "0" */
sgnS: lambda([x], if x > 0 then sconcat("+", x) else if x < 0 then sconcat("-", -x) else "0");
Es: map(sgnS, eff);
dtS: sgnS(dt);
noiseS: sgnS(noise);

/* Teacher's answers: day, time and traffic news */
ta1: [1, 2, 5];
ta2: typical + dt + eff[5];
ta3: actual + 15;

feedbackvariables.text:
sel: if listp(ans1) then ans1 else [];
sel: unique(sublist(sel, lambda([x], integerp(x) and x >= 1 and x <= 6)));
hasD: member(1, sel);
hasT: member(2, sel);
whenAcc: if hasD and hasT then dt else if hasD then dayM[di] else if hasT then timeM[ti] else 0;
whenRem: dt - whenAcc;
otherAcc: apply("+", cons(0, map(lambda([k], eff[k]), sublist(sel, lambda([k], k >= 3)))));
accMin: whenAcc + otherAcc;
pred: typical + accMin;
accS: sgnS(accMin);
whenAccS: sgnS(whenAcc);
whenRemS: sgnS(whenRem);
ncards: length(sel);
extra: max(0, ncards - 2);

sel: if listp(ans1) then ans1 else [];
sel: unique(sublist(sel, lambda([x], integerp(x) and x >= 1 and x <= 6)));
hasD: member(1, sel);
hasT: member(2, sel);
whenAcc: if hasD and hasT then dt else if hasD then dayM[di] else if hasT then timeM[ti] else 0;
whenRem: dt - whenAcc;
otherAcc: apply("+", cons(0, map(lambda([k], eff[k]), sublist(sel, lambda([k], k >= 3)))));
accMin: whenAcc + otherAcc;
pred: typical + accMin;
accS: sgnS(accMin);
whenAccS: sgnS(whenAcc);
whenRemS: sgnS(whenRem);
ncards: length(sel);
extra: max(0, ncards - 2);
hid: sublist([3, 4, 5, 6], lambda([k], not member(k, sel)));
unaccMin: whenRem + apply("+", cons(0, map(lambda([k], eff[k]), hid)));
unaccS: sgnS(unaccMin);
wait: ans3 - actual;
late: actual - ans3;
cost: 0.1 * extra;
sFull: max(0, 1 - cost);
sHalf: max(0, 0.5 - cost);
/* biggest single face-down contribution */
candN: append(if whenRem # 0 then ["Day and time of day"] else [], map(lambda([k], cardn[k]), hid));
candV: append(if whenRem # 0 then [whenRem] else [], map(lambda([k], eff[k]), hid));
candA: map(abs, candV);
bigI: if candA = [] then 0 else (if lmax(candA) = 0 then 0 else first(sublist_indices(candA, lambda([x], x = lmax(candA)))));
